-- =============================================================================
-- SUPABASE DATABASE SCHEMA - Aluminium Window Quotation System
-- =============================================================================
-- 
-- ⚠️ IMPORTANT: DO NOT EDIT THIS FILE DIRECTLY DURING DEVELOPMENT
-- 
-- This file contains the COMPLETE database schema for first-time setup.
-- 
-- WORKFLOW FOR CHANGES:
-- 1. Add new changes to updates.sql (NOT here)
-- 2. Test in Supabase SQL Editor
-- 3. After confirmation, merge changes HERE
-- 4. Clear updates.sql
-- 
-- See DATABASE_WORKFLOW.md for detailed instructions.
-- See .kiro/steering/database-rules.md for AI assistant rules.
-- =============================================================================

-- Execute these commands in your Supabase SQL Editor

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Users Table (extends Supabase auth.users)
CREATE TABLE public.profiles (
  id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  full_name TEXT NOT NULL,
  company_name TEXT,
  phone TEXT,
  role TEXT CHECK (role IN ('superadmin', 'admin', 'user', 'sales', 'accounts')) DEFAULT 'user',
  -- Per-user account controls (managed by the superadmin).
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  can_access_designs BOOLEAN NOT NULL DEFAULT TRUE,
  can_access_billing BOOLEAN NOT NULL DEFAULT TRUE,
  can_access_inventory BOOLEAN NOT NULL DEFAULT TRUE,
  avatar_url TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Clients Table
CREATE TABLE public.clients (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT,
  phone TEXT NOT NULL,
  address TEXT,
  company TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Window Templates Table
CREATE TABLE public.window_templates (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  window_type TEXT CHECK (window_type IN ('sliding', 'casement', 'fixed', 'door', 'combination')) NOT NULL,
  default_width NUMERIC NOT NULL,
  default_height NUMERIC NOT NULL,
  image_url TEXT,
  description TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Window Designs Table
CREATE TABLE public.window_designs (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  template_id UUID REFERENCES public.window_templates(id),
  window_type TEXT NOT NULL,
  width NUMERIC NOT NULL,
  height NUMERIC NOT NULL,
  profile_type TEXT NOT NULL,
  glass_type TEXT NOT NULL,
  glass_thickness NUMERIC NOT NULL,
  color TEXT NOT NULL,
  hardware JSONB DEFAULT '[]'::JSONB,
  preview_image TEXT,
  editor_document JSONB,
  -- A design belongs to a quotation (nullable so the standalone editor works).
  -- FK added after the quotations table is created (see ALTER below).
  quotation_id UUID,
  -- Persisted pricing for cheap quotation aggregation.
  area_sqft NUMERIC NOT NULL DEFAULT 0,
  rate_per_sqft NUMERIC NOT NULL DEFAULT 0,
  amount NUMERIC NOT NULL DEFAULT 0,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Fast lookup of all designs for a quotation.
CREATE INDEX IF NOT EXISTS window_designs_quotation_id_idx
  ON public.window_designs (quotation_id);

-- =============================================================================
-- Design editor configurable lists + pricing
-- =============================================================================
-- Shared columns on every list table: name, is_active, is_default, sort_order.

-- Glass options.
CREATE TABLE public.design_glasses (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  rate_per_sqft NUMERIC NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Colour / finish options.
CREATE TABLE public.design_colors (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  hex TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- GI hardware lists (galvanized iron sections).
CREATE TABLE public.gi_tracks (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  profile_code TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

CREATE TABLE public.gi_sashes (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  profile_code TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

CREATE TABLE public.gi_interlocks (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  profile_code TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

CREATE TABLE public.gi_locks (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  profile_code TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Per-window-type base rate.
CREATE TABLE public.design_type_rates (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  window_type TEXT NOT NULL UNIQUE,
  base_rate NUMERIC NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Single-row global pricing config.
CREATE TABLE public.design_pricing_config (
  id INTEGER PRIMARY KEY DEFAULT 1,
  gst_percentage NUMERIC NOT NULL DEFAULT 18,
  install_percentage NUMERIC NOT NULL DEFAULT 10,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  CONSTRAINT design_pricing_config_singleton CHECK (id = 1)
);

-- Typed, per-user accessories picked per window section in the editor.
-- `kind` groups them so the editor shows the right dropdown
-- (Sash / Interlock / Handle / Roller / Lock / Hinge / Mesh).
CREATE TABLE public.design_accessories (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN (
    'sash','interlock','handle','roller','lock','hinge','mesh',
    'mesh_type','mesh_sash','mesh_clip','mesh_handle','mesh_slim',
    'reinforcement','slim_interlock','friction_stay'
  )),
  name TEXT NOT NULL,
  code TEXT,
  price NUMERIC NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

CREATE INDEX IF NOT EXISTS design_accessories_owner_kind_idx
  ON public.design_accessories (created_by, kind);

-- One row per user holding the aluminium cost heads used to price a window.
-- Values mirror the reference "Aluminium Setting" cost sheet.
CREATE TABLE public.aluminium_cost_settings (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id UUID NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,
  aluminium_rate NUMERIC NOT NULL DEFAULT 0,      -- Rs / Kg
  profit_percentage NUMERIC NOT NULL DEFAULT 0,   -- %
  labour_charge NUMERIC NOT NULL DEFAULT 0,       -- Rs / Sqft
  coating NUMERIC NOT NULL DEFAULT 0,             -- Rs / Kg
  corner_cleat NUMERIC NOT NULL DEFAULT 0,        -- Rs / qty
  weather_strip NUMERIC NOT NULL DEFAULT 0,       -- Rs / meter
  ss_corner_con NUMERIC NOT NULL DEFAULT 0,       -- Rs / piece
  screw NUMERIC NOT NULL DEFAULT 0,               -- Rs / piece
  rail NUMERIC NOT NULL DEFAULT 0,                -- Rs / meter
  fastner NUMERIC NOT NULL DEFAULT 0,             -- Rs / piece
  -- Overlaps (mm) that affect cut sizes; used by the BOM engine later.
  slider_width_overlap NUMERIC NOT NULL DEFAULT 25,
  slider_height_overlap NUMERIC NOT NULL DEFAULT 18,
  slider_glass_overlap NUMERIC NOT NULL DEFAULT 16,
  casement_width_overlap NUMERIC NOT NULL DEFAULT 12,
  casement_height_overlap NUMERIC NOT NULL DEFAULT 12,
  casement_glass_overlap NUMERIC NOT NULL DEFAULT 20,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- =============================================================================
-- Billing periods (admin-managed multi-user)
-- =============================================================================
-- Each row is one billing cycle for a user. The ACTIVE period is the one whose
-- [starts_at, ends_at] range contains today. It carries the quotation limit
-- (NULL = unlimited) that resets each period, and acts as the account expiry.
CREATE TABLE public.billing_periods (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  plan_name TEXT NOT NULL DEFAULT 'Standard',
  amount NUMERIC NOT NULL DEFAULT 0,
  starts_at DATE NOT NULL DEFAULT CURRENT_DATE,
  ends_at DATE NOT NULL,
  quotation_limit INTEGER, -- NULL = unlimited
  is_paid BOOLEAN NOT NULL DEFAULT FALSE,
  notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

CREATE INDEX IF NOT EXISTS billing_periods_user_id_idx
  ON public.billing_periods (user_id);
CREATE INDEX IF NOT EXISTS billing_periods_range_idx
  ON public.billing_periods (user_id, starts_at, ends_at);

-- Superadmin check used across RLS. SECURITY DEFINER avoids recursive policy
-- evaluation when reading profiles.role.
CREATE OR REPLACE FUNCTION public.is_superadmin()
RETURNS BOOLEAN AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'superadmin'
  );
$$ LANGUAGE sql SECURITY DEFINER STABLE;

-- Profiles (Aluminium/UPVC) Table
CREATE TABLE public.profiles_inventory (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT CHECK (type IN ('aluminium', 'upvc')) NOT NULL,
  weight_per_meter NUMERIC NOT NULL,
  cost_per_kg NUMERIC NOT NULL,
  cost_per_meter NUMERIC NOT NULL,
  stock_quantity NUMERIC DEFAULT 0,
  unit TEXT DEFAULT 'meters',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Glass Inventory Table
CREATE TABLE public.glass_inventory (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  type TEXT NOT NULL,
  thickness NUMERIC NOT NULL,
  cost_per_sqft NUMERIC NOT NULL,
  stock_quantity NUMERIC DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Accessories Table
CREATE TABLE public.accessories (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  cost NUMERIC NOT NULL,
  stock_quantity INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Quotations Table
CREATE TABLE public.quotations (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  quotation_number TEXT UNIQUE NOT NULL,
  client_id UUID REFERENCES public.clients(id),
  client_name TEXT NOT NULL,
  client_email TEXT,
  client_phone TEXT NOT NULL,
  status TEXT CHECK (status IN ('draft', 'sent', 'approved', 'rejected')) DEFAULT 'draft',
  total_amount NUMERIC NOT NULL DEFAULT 0,
  items JSONB DEFAULT '[]'::JSONB,
  notes TEXT,
  valid_until DATE,
  -- Quotation-level cost overheads (GST + charges applied once per quotation;
  -- design amounts are pre-tax). See lib/quotation-pricing.ts.
  profit_percentage NUMERIC NOT NULL DEFAULT 0,
  installation_charge NUMERIC NOT NULL DEFAULT 0,   -- Rs / Sqft
  labour_charge NUMERIC NOT NULL DEFAULT 0,          -- Rs / Sqft
  profile_wastage NUMERIC NOT NULL DEFAULT 0,        -- %
  glass_wastage NUMERIC NOT NULL DEFAULT 0,          -- %
  transport_charge NUMERIC NOT NULL DEFAULT 0,       -- Rs flat
  discount NUMERIC NOT NULL DEFAULT 0,
  discount_type TEXT NOT NULL DEFAULT 'percentage'
    CHECK (discount_type IN ('percentage','fixed')),
  cgst NUMERIC NOT NULL DEFAULT 9,                   -- %
  sgst NUMERIC NOT NULL DEFAULT 9,                   -- %
  igst NUMERIC NOT NULL DEFAULT 0,                   -- %
  gst_mode TEXT NOT NULL DEFAULT 'cgst_sgst'
    CHECK (gst_mode IN ('cgst_sgst','igst','none')),
  grand_total NUMERIC NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Arbitrary custom cost-head line items for a quotation (Pricing page).
CREATE TABLE public.quotation_cost_heads (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  quotation_id UUID NOT NULL REFERENCES public.quotations(id) ON DELETE CASCADE,
  label TEXT NOT NULL,
  amount NUMERIC NOT NULL DEFAULT 0,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

CREATE INDEX IF NOT EXISTS quotation_cost_heads_quotation_idx
  ON public.quotation_cost_heads (quotation_id);

-- Now that quotations exists, link window_designs.quotation_id to it.
ALTER TABLE public.window_designs
  ADD CONSTRAINT window_designs_quotation_id_fkey
  FOREIGN KEY (quotation_id) REFERENCES public.quotations(id) ON DELETE CASCADE;

-- Invoices Table
CREATE TABLE public.invoices (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  invoice_number TEXT UNIQUE NOT NULL,
  quotation_id UUID REFERENCES public.quotations(id),
  client_id UUID REFERENCES public.clients(id),
  amount NUMERIC NOT NULL,
  paid_amount NUMERIC DEFAULT 0,
  status TEXT CHECK (status IN ('pending', 'partial', 'paid')) DEFAULT 'pending',
  due_date DATE,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Calculation Formulas Table
CREATE TABLE public.calculation_formulas (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  profile_weight_formula TEXT,
  glass_area_formula TEXT,
  labour_cost_per_sqft NUMERIC DEFAULT 0,
  markup_percentage NUMERIC DEFAULT 0,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Row Level Security (RLS) Policies
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.window_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.window_designs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles_inventory ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.glass_inventory ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.accessories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quotations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quotation_cost_heads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calculation_formulas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.design_glasses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.design_colors ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gi_tracks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gi_sashes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gi_interlocks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gi_locks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.design_type_rates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.design_pricing_config ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_periods ENABLE ROW LEVEL SECURITY;

-- Per-user ownership with superadmin override. Owners access rows where
-- created_by = auth.uid(); superadmin accesses everything.

-- Profiles: own row, or superadmin.
CREATE POLICY "profiles_select" ON public.profiles
  FOR SELECT USING (auth.uid() = id OR public.is_superadmin());
CREATE POLICY "profiles_insert" ON public.profiles
  FOR INSERT WITH CHECK (auth.uid() = id OR public.is_superadmin());
CREATE POLICY "profiles_update" ON public.profiles
  FOR UPDATE USING (auth.uid() = id OR public.is_superadmin());
CREATE POLICY "profiles_delete" ON public.profiles
  FOR DELETE USING (public.is_superadmin());

-- Clients.
CREATE POLICY "clients_select" ON public.clients
  FOR SELECT USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "clients_insert" ON public.clients
  FOR INSERT WITH CHECK (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "clients_update" ON public.clients
  FOR UPDATE USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "clients_delete" ON public.clients
  FOR DELETE USING (created_by = auth.uid() OR public.is_superadmin());

-- Window templates (public read).
CREATE POLICY "Anyone can view window templates" ON public.window_templates
  FOR SELECT USING (true);

-- Window designs.
CREATE POLICY "designs_select" ON public.window_designs
  FOR SELECT USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "designs_insert" ON public.window_designs
  FOR INSERT WITH CHECK (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "designs_update" ON public.window_designs
  FOR UPDATE USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "designs_delete" ON public.window_designs
  FOR DELETE USING (created_by = auth.uid() OR public.is_superadmin());

-- Inventory policies
CREATE POLICY "Authenticated users can view profiles inventory" ON public.profiles_inventory
  FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Authenticated users can view glass inventory" ON public.glass_inventory
  FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Authenticated users can view accessories" ON public.accessories
  FOR SELECT USING (auth.role() = 'authenticated');

-- Quotations.
CREATE POLICY "quotations_select" ON public.quotations
  FOR SELECT USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "quotations_insert" ON public.quotations
  FOR INSERT WITH CHECK (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "quotations_update" ON public.quotations
  FOR UPDATE USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "quotations_delete" ON public.quotations
  FOR DELETE USING (created_by = auth.uid() OR public.is_superadmin());

-- Invoices.
CREATE POLICY "invoices_select" ON public.invoices
  FOR SELECT USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "invoices_insert" ON public.invoices
  FOR INSERT WITH CHECK (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "invoices_update" ON public.invoices
  FOR UPDATE USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "invoices_delete" ON public.invoices
  FOR DELETE USING (created_by = auth.uid() OR public.is_superadmin());

-- Billing periods: a user reads own; only superadmin writes.
CREATE POLICY "billing_periods_select" ON public.billing_periods
  FOR SELECT USING (user_id = auth.uid() OR public.is_superadmin());
CREATE POLICY "billing_periods_write" ON public.billing_periods
  FOR ALL USING (public.is_superadmin()) WITH CHECK (public.is_superadmin());

-- Per-user accessories: owner reads/writes own rows; superadmin all.
ALTER TABLE public.design_accessories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "design_accessories_select" ON public.design_accessories
  FOR SELECT USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "design_accessories_insert" ON public.design_accessories
  FOR INSERT WITH CHECK (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "design_accessories_update" ON public.design_accessories
  FOR UPDATE USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "design_accessories_delete" ON public.design_accessories
  FOR DELETE USING (created_by = auth.uid() OR public.is_superadmin());

-- Per-user aluminium cost settings: owner reads/writes own row; superadmin all.
ALTER TABLE public.aluminium_cost_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "aluminium_cost_settings_select" ON public.aluminium_cost_settings
  FOR SELECT USING (user_id = auth.uid() OR public.is_superadmin());
CREATE POLICY "aluminium_cost_settings_insert" ON public.aluminium_cost_settings
  FOR INSERT WITH CHECK (user_id = auth.uid() OR public.is_superadmin());
CREATE POLICY "aluminium_cost_settings_update" ON public.aluminium_cost_settings
  FOR UPDATE USING (user_id = auth.uid() OR public.is_superadmin());

-- Quotation custom cost heads: owner (created_by) or superadmin.
CREATE POLICY "quotation_cost_heads_select" ON public.quotation_cost_heads
  FOR SELECT USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "quotation_cost_heads_insert" ON public.quotation_cost_heads
  FOR INSERT WITH CHECK (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "quotation_cost_heads_update" ON public.quotation_cost_heads
  FOR UPDATE USING (created_by = auth.uid() OR public.is_superadmin());
CREATE POLICY "quotation_cost_heads_delete" ON public.quotation_cost_heads
  FOR DELETE USING (created_by = auth.uid() OR public.is_superadmin());

-- Design editor lists: all authenticated users read; only superadmin writes.
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'design_glasses','design_colors','gi_tracks','gi_sashes',
    'gi_interlocks','gi_locks','design_type_rates','design_pricing_config'
  ]
  LOOP
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR SELECT USING (auth.role() = ''authenticated'')',
      t || '_select', t
    );
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR ALL USING (public.is_superadmin()) WITH CHECK (public.is_superadmin())',
      t || '_write', t
    );
  END LOOP;
END $$;

-- Functions for automatic quotation number generation
CREATE OR REPLACE FUNCTION generate_quotation_number()
RETURNS TEXT AS $$
DECLARE
  next_number INTEGER;
  quotation_number TEXT;
BEGIN
  SELECT COUNT(*) + 1 INTO next_number FROM public.quotations;
  quotation_number := 'QT' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(next_number::TEXT, 4, '0');
  RETURN quotation_number;
END;
$$ LANGUAGE plpgsql;

-- Trigger to auto-generate quotation number
CREATE OR REPLACE FUNCTION set_quotation_number()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.quotation_number IS NULL OR NEW.quotation_number = '' THEN
    NEW.quotation_number := generate_quotation_number();
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER generate_quotation_number_trigger
  BEFORE INSERT ON public.quotations
  FOR EACH ROW
  EXECUTE FUNCTION set_quotation_number();

-- Function for automatic invoice number generation
CREATE OR REPLACE FUNCTION generate_invoice_number()
RETURNS TEXT AS $$
DECLARE
  next_number INTEGER;
  invoice_number TEXT;
BEGIN
  SELECT COUNT(*) + 1 INTO next_number FROM public.invoices;
  invoice_number := 'INV' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(next_number::TEXT, 4, '0');
  RETURN invoice_number;
END;
$$ LANGUAGE plpgsql;

-- Trigger to auto-generate invoice number
CREATE OR REPLACE FUNCTION set_invoice_number()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.invoice_number IS NULL OR NEW.invoice_number = '' THEN
    NEW.invoice_number := generate_invoice_number();
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER generate_invoice_number_trigger
  BEFORE INSERT ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION set_invoice_number();

-- Auto-create a profile row when a new auth user signs up.
-- SECURITY DEFINER lets it bypass RLS. Pulls full_name/company_name from the
-- signup metadata (options.data) passed by the client.
-- New users default to role 'user' (or an explicit role passed in signup
-- metadata). The superadmin is promoted by the seed below.
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, company_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NULLIF(NEW.raw_user_meta_data->>'full_name', ''), split_part(NEW.email, '@', 1)),
    NEW.raw_user_meta_data->>'company_name',
    COALESCE(NULLIF(NEW.raw_user_meta_data->>'role', ''), 'user')
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

-- Backfill profiles for any existing auth users missing one (keeps the
-- created_by foreign keys valid for accounts created before the trigger).
INSERT INTO public.profiles (id, email, full_name, company_name, role)
SELECT
  u.id,
  u.email,
  COALESCE(NULLIF(u.raw_user_meta_data->>'full_name', ''), split_part(u.email, '@', 1)),
  u.raw_user_meta_data->>'company_name',
  'user'
FROM auth.users u
LEFT JOIN public.profiles p ON p.id = u.id
WHERE p.id IS NULL
ON CONFLICT (id) DO NOTHING;

-- Superadmin seed. Promote admin@gmail.com (create the AUTH login separately in
-- the Supabase Dashboard → Authentication → Users). Idempotent.
UPDATE public.profiles
  SET role = 'superadmin', is_active = TRUE
  WHERE email = 'admin@gmail.com';

INSERT INTO public.profiles (id, email, full_name, role, is_active)
SELECT u.id, u.email, 'Super Admin', 'superadmin', TRUE
FROM auth.users u
LEFT JOIN public.profiles p ON p.id = u.id
WHERE u.email = 'admin@gmail.com' AND p.id IS NULL
ON CONFLICT (id) DO UPDATE SET role = 'superadmin', is_active = TRUE;

